1.4.7 @NotEmpty @NotNull @NotBlank @NotBlank用于String类型 “The difference to {@code NotEmpty} is that trailingwhitespaces are getting ignored.” –&gt; 和{@code NotEmpty}不同的是，尾部空格被忽略，也就是说，纯空格的String也是不符合规则的。所以才会说@NotBlank用于String，只能作用在String上，不能为null，而且调用trim()后，长度必须大于0。
@NotEmpty的String类、Collection、Map、数组，是不能为null并且长度必须大于0的（String、Collection、Map的isEmpty()方法）。
@NotNull 这个就很好理解了，不能为null，但可以为empty。
// 全局处理字符串两端字符@Configurationpublic class GenGlobalCodeUtilsConfig &#123; @Bean public Jackson2ObjectMapperBuilderCustomizer jackson2ObjectMapperBuilderCustomizer()&#123; return new Jackson2ObjectMapperBuilderCustomizer() &#123; @Override public void customize(Jackson2ObjectMapperBuilder jacksonObjectMapperBuilder) &#123; jacksonObjectMapperBuilder.deserializerByType(String.class, new StdScalarDeserializer&lt;String&gt;(String.class) &#123; private static final long serialVersionUID = 1L; @Override public String deserialize(JsonParser jsonParser, DeserializationContext deserializationContext) throws IOException, JacksonException &#123; return StringUtils.trimAllWhitespace(jsonParser.getValueAsString()); &#125; &#125;); &#125; &#125;; &#125;&#125;
1.4.8 流程回退// 1.一退一runtimeService.createChangeActivityStateBuilder() .processInstanceId(proInstanceId) .moveActivityIdsToSingleActivityId(curTaskKeys, targetTaskKey) .changeState();// 2.一退多List&lt;String &gt; targetTaskKeys = new ArrayList&lt;&gt;();targetTaskKeys.add(&quot;sid-CA74ADED-7E70-451D-951C-95988BFC3F07&quot;);targetTaskKeys.add(&quot;sid-7922C598-74FD-4848-95AC-D9790AF68432&quot;);runtimeService.createChangeActivityStateBuilder() .processInstanceId(proInstanceId) .moveSingleActivityIdToActivityIds(&quot;sid-CAD50E6F-7E0C-437D-816B-DDBA1A976A79&quot;, targetTaskKeys) .changeState();// 3. 多退一List&lt;String &gt; currentExecutionIds = new ArrayList&lt;&gt;();List&lt;Execution&gt; executions = runtimeService.createExecutionQuery().parentId(proInstanceId).list();for (Execution execution : executions) &#123; System.out.println(&quot;并行网关节点数：&quot;+execution.getActivityId()); currentExecutionIds.add(execution.getId());&#125;runtimeService.createChangeActivityStateBuilder() .processInstanceId(proInstanceId) .moveExecutionsToSingleActivityId(currentExecutionIds, targetTaskKey) .changeState();// 4.子流程中退回到主干流程中某一个节点/主干流程退回到子流程中某一个节点。
1.4.9 审批 审批就是推进一次，可以带map参数 1.4.10 aop@Aspect@Componentpublic class StringTrimAop &#123; // 定义切点方法 controller 包下，子孙包下所有类的所有方法 @Pointcut(&quot;execution(* com.pfa.practice.controller.*.*(..))&quot;)// @Pointcut(&quot;@annotation(com.pfa.practice.annotations.StringTrim)&quot;) // 只能拦截方法 弃用 public void pointcut() &#123; System.out.println(&quot;切入点，并不会执行&quot;); &#125; // 前置方法 @Before(&quot;pointcut()&quot;) public void doBefore(JoinPoint joinPoint) throws Throwable &#123; // 获取当前访问的class类及类名 Class&lt;?&gt; tClass = joinPoint.getTarget().getClass(); Validated validated = joinPoint.getTarget().getClass().getAnnotation(Validated.class); if (validated != null) &#123; // 获取访问的方法名 String methodName = joinPoint.getSignature().getName(); System.out.println(methodName+&quot;方法被捕获了&quot;); // 获取方法所有参数及其类型 Object[] args = joinPoint.getArgs(); Class[] argClz = ((MethodSignature) joinPoint.getSignature()).getParameterTypes(); // 获取访问的方法对象 Method method = tClass.getDeclaredMethod(methodName, argClz); Annotation[] declaredAnnotations = method.getDeclaredAnnotations(); &#125; System.out.println(&quot;这里执行前置方法逻辑&quot;); &#125;// @Around(&quot;pointcut()&quot;)// public Object doAround(ProceedingJoinPoint proceedingJoinPoint) &#123;// Object obj = null;// System.out.println(&quot;Around 方法开始执行&quot;);// try &#123;// // 执行拦截方法// obj = proceedingJoinPoint.proceed();// &#125; catch (Throwable throwable) &#123;// throwable.printStackTrace();// &#125;// System.out.println(&quot;Around 方法结束执行&quot;);// return obj;// &#125;&#125;
